-- LOCAL ONLY: keep the visible report summary and its stored copies consistent.
BEGIN;
UPDATE public.personal_assessment_results
SET overall_summary='Rohan is a second-year MBA learner with strong numerical reasoning, data interpretation and communication skills. His organised approach and interest in sustainable business align with water-project coordination, financial planning, procurement and stakeholder management. Developing practical experience in project reporting, environmental data analysis and compliance documentation can strengthen his readiness for these roles.',
 gemini_results=jsonb_set(jsonb_set(jsonb_set(gemini_results,'{overallSummary}',to_jsonb('Rohan is a second-year MBA learner with strong numerical reasoning, data interpretation and communication skills. His organised approach and interest in sustainable business align with water-project coordination, financial planning, procurement and stakeholder management. Developing practical experience in project reporting, environmental data analysis and compliance documentation can strengthen his readiness for these roles.'::text)),'{profileNarrative,summary}',to_jsonb('Rohan is a second-year MBA learner with strong numerical reasoning, data interpretation and communication skills. His organised approach and interest in sustainable business align with water-project coordination, financial planning, procurement and stakeholder management. Developing practical experience in project reporting, environmental data analysis and compliance documentation can strengthen his readiness for these roles.'::text)),'{profileNarrative}',jsonb_build_object('summary','Rohan is a second-year MBA learner with strong numerical reasoning, data interpretation and communication skills. His organised approach and interest in sustainable business align with water-project coordination, financial planning, procurement and stakeholder management. Developing practical experience in project reporting, environmental data analysis and compliance documentation can strengthen his readiness for these roles.'))
WHERE id='851403af-f1a6-5d48-94e2-0a4b6e2e47ae'
 AND learner_id=(SELECT id FROM public.learners WHERE user_id='02f0a43d-3c0a-5026-b44f-5d0696e75f19'::uuid AND email='rohan.iyer.mba@example.com');
